pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score proportional to remaining space – smaller is better
    let mut score = post_residual as f64;

    // Aggressive penalty for tiny leftovers (dead space)
    if post_residual < 5 {
        score += 20.0;
    }

    // Prefer existing bins over opening a new one
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        // Empty bin with no fitters – high penalty
        score += 40.0;
    } else if bin_residual == bin_capacity && fitting_bins_count > 0 {
        // Empty bin but there are fitters – moderate penalty
        score += 15.0;
    }

    // Open‑bin pressure: more open bins → higher score
    let open_pressure = (open_bins_count as f64).ln() * 0.25;
    score += open_pressure;

    // Penalize if the residual ratio diverges from the mean residual ratio
    let res_ratio = post_residual as f64 / bin_capacity as f64;
    let mean_ratio = mean_residual / bin_capacity as f64;
    score += (res_ratio - mean_ratio).abs() * 12.0;

    // Next‑item lookahead: discourage leaving space that cannot fit the next item
    if next_item_size > post_residual {
        let diff = next_item_size as i32 - post_residual as i32;
        score += diff as f64 * 0.5 + 50.0;
    } else {
        score -= 10.0;
    }

    // Fitting‑bin count weighting: encourage bins that have many potential fitters
    if fitting_bins_count <= 1 {
        score += 30.0;
    } else {
        let extra = ((fitting_bins_count as f64) - 1.0).ln() * 3.0;
        let penalty = ((fitting_bins_count as f64) - 3.0).max(0.0) * 8.0;
        score += extra + penalty;
    }

    // Late‑stage penalty to avoid poor packing when most items are processed
    let progress = (step_index as f64) / (total_items as f64);
    if progress > 0.9 {
        let late_penalty = res_ratio * 150.0 * (1.0 + progress);
        score += late_penalty;
    }

    // Final adjustment for excessive open bins
    if open_bins_count > 12 {
        score += (open_bins_count as f64 - 12.0) * 2.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Core residual cost – lower residual after packing is better
    let mut score = post_residual as f64 * 1.0;

    // Relative residual against the global mean – penalise large swings
    let bin_cap_f = bin_capacity as f64;
    let res_ratio = post_residual as f64 / bin_cap_f;
    let mean_ratio = mean_residual / bin_cap_f;
    score += (res_ratio - mean_ratio).abs() * 5.0;

    // Open‑bin pressure – logarithmic penalty encourages fewer bins
    score += (open_bins_count as f64).ln() * 3.0;
    if open_bins_count > 12 {
        score += 20.0; // extra penalty for very many open bins
    }

    // Progress‑dependent pressure – late in the stream we want tighter packing
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    if progress > 0.8 {
        score += post_residual as f64 * 2.0;
    }

    // Next‑item fit test – reward bins that can still hold the next item
    if next_item_size > post_residual {
        let diff = (next_item_size as i32 - post_residual as i32) as f64;
        score += diff * 0.5 + 50.0;
    } else {
        score -= 10.0; // small bonus if the next item will fit
    }

    // Fitting‑bins count – few options should be rewarded, many options penalised
    if fitting_bins_count <= 2 {
        score -= 20.0;
    } else {
        score += ((fitting_bins_count as f64) - 2.0).ln() * 4.0;
    }

    // Large items – prefer bins that still leave enough space after placement
    let item_ratio = item_size as f64 / bin_cap_f;
    if item_ratio > 0.7 {
        score += post_residual as f64 * 1.5;
    }

    // New bin candidate – only attractive if overall packing is poor
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        let avg_factor = 1.0 - (mean_residual / bin_cap_f).min(1.0);
        score += 30.0 * avg_factor;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base cost: leftover space after placement
    let mut score = post_residual as f64;

    // Progress factor: fraction of stream processed
    let progress = (step_index as f64) / (total_items as f64).max(1.0);

    // Open‑bin penalty with logarithmic growth, scaled by progress
    let open_pen = (open_bins_count as f64).ln().max(1.0)
        * (0.2 + 0.6 * progress);
    score += open_pen;

    // Residual‑ratio vs mean‑ratio comparison
    let mean_ratio = mean_residual / bin_capacity as f64;
    let residual_ratio = post_residual as f64 / bin_capacity as f64;

    if residual_ratio < mean_ratio * 0.9 {
        let diff = (mean_residual - post_residual as f64).max(0.0);
        score += diff * 0.8;
        if residual_ratio < mean_ratio * 0.5 {
            score += 300.0; // severe dead‑space penalty
        }
    }

    // Exact or near‑exact fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 5 {
        score -= 20.0;
    }

    // Look‑ahead penalty for inability to fit the next item
    if next_item_size > 0 && next_item_size > post_residual {
        let diff = (next_item_size - post_residual) as f64;
        score += diff.powi(2) * 0.015 + 70.0;
    }

    // Crowding penalty: discourage heavily used bins
    if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64 - 3.0) * 5.0;
    }

    // Prefer bins with a single fitting slot
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 3.0;
    }

    // New‑bin candidacy: cheaper when average residual is high
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let avg_factor = 1.0 - (mean_residual / bin_capacity as f64).min(1.0);
        score += 50.0 * avg_factor + 10.0 * (fitting_bins_count as f64);
    }

    // Late‑stream tightening: heavily penalise large residuals near the end
    if progress > 0.9 {
        let late_pen = (post_residual as f64 / bin_capacity as f64) * 250.0 * progress;
        score += late_pen;
    }

    // Bonus for a perfect fit to the remaining residual
    let fit_ratio = item_size as f64 / (bin_residual as f64).max(1);
    if fit_ratio > 0.95 {
        score -= 10.0;
    }

    // Extra penalty if too many open bins – encourage early consolidation
    if open_bins_count > 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: linear + quadratic residual penalty
    let mut score = post_residual as f64 + (post_residual as f64).powi(2) * 0.0001;

    // Progress factor (0..1)
    let progress = (step_index as f64) / (total_items as f64).max(1.0);

    // Open bins penalty (soft)
    let open_pen = (open_bins_count as f64).ln().max(1.0) * (0.2 + 0.1 * progress);
    score += open_pen;

    // Residual ratio penalty (compactness)
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    if residual_ratio < 0.25 {
        score += 500.0;
    } else if residual_ratio < 0.5 {
        score += 200.0;
    } // otherwise no penalty

    // Extra penalty for excessive residual (>0.75)
    if residual_ratio > 0.75 {
        score += 50.0 * (residual_ratio - 0.75);
    }

    // Item size fraction adjustments
    let item_frac = item_size as f64 / bin_capacity as f64;
    if item_frac > 0.7 {
        score += 30.0;
    } else if item_frac > 0.5 {
        score += 10.0;
    }

    // Look‑ahead with next item
    if next_item_size > 0 {
        let diff = next_item_size as i32 - post_residual as i32;
        if diff > 0 {
            score += diff as f64 * 0.5 + 80.0;
        } else if diff <= -(post_residual as i32) / 3 {
            score -= 10.0;
        }
    }

    // Fitting bins count handling
    if fitting_bins_count == 0 {
        score += 300.0;
    } else if fitting_bins_count == 1 {
        score -= 30.0; // slight reward for unique fit
    } else {
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New bin candidate adjustment
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let avg_factor = (mean_residual / bin_capacity as f64).min(1.0);
        score += 70.0 * (1.0 - avg_factor) + 5.0 * fitting_bins_count as f64;
    }
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score += 40.0;
    } else if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 15.0;
    }

    // Late‑stage penalty to reduce waste
    if progress > 0.8 {
        let late_pen = (post_residual as f64 / bin_capacity as f64) * 200.0 * progress;
        score += late_pen;
    }

    // Mean residual variance penalty
    let mean_diff = (mean_residual - post_residual as f64).abs();
    if mean_diff > 15.0 {
        score += mean_diff * 0.08;
    }
    if mean_diff > 30.0 {
        score += (mean_diff - 30.0) * 0.05;
    }

    // Penalize bins far from mean residual
    if (post_residual as f64 - mean_residual).abs() > 0.5 * mean_residual {
        score += (post_residual as f64 - mean_residual).abs() * 0.05;
    }

    // Mildly encourage opening a new bin when many bins are already open
    if open_bins_count > 5 {
        score += 0.02 * (open_bins_count as f64).powi(2);
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // --- Base score: remaining space after placement ---
    let mut score = post_residual as f64;

    // --- Progress‑dependent open‑bin penalty ---
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    score += (open_bins_count as f64) * (0.3 + 0.4 * progress);

    // --- Residual versus mean residual ratio ---
    let bin_cap_f = bin_capacity as f64;
    let res_ratio = post_residual as f64 / bin_cap_f;
    let mean_ratio = mean_residual / bin_cap_f;

    if res_ratio < mean_ratio * 0.9 {
        let diff = (mean_residual - post_residual as f64).max(0.0);
        score += diff * 2.0;
        if res_ratio < mean_ratio * 0.6 {
            score += 600.0; // severe dead space
        }
    }

    // --- Look‑ahead penalty for the next item ---
    if next_item_size > 0 && (next_item_size as u32) > post_residual {
        let diff = (next_item_size as i32 - post_residual as i32) as f64;
        score += diff * 0.3 + 120.0;
    }

    // --- Fitting bin preference / discouragement ---
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // slight penalty for crowded bins
        score += ((fitting_bins_count as f64) - 1.0).ln() * 5.0;
        if fitting_bins_count > 3 {
            score += ((fitting_bins_count as f64) - 3.0) * 12.0;
        }
    }

    // --- New‑bin candidacy ---
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let avg_factor = 1.0 - (mean_residual / bin_cap_f).min(1.0);
        score += 60.0 * avg_factor + 15.0 * (fitting_bins_count as f64);
    }

    // --- Late‑stream tightening ---
    if progress > 0.9 {
        let late_penalty = res_ratio * 250.0 * progress;
        score += late_penalty;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let post_residual_f = post_residual as f64;
    let bin_cap_f = bin_capacity as f64;
    let residual_ratio = post_residual_f / bin_cap_f;

    // Base waste penalty (quadratic to discourage large waste)
    let mut score = post_residual_f + post_residual_f.powi(2) * 0.0001;

    // Residual ratio penalty / reward
    if residual_ratio < 0.2 {
        score += 350.0; // very tight fit is bad due to fragmentation
    } else if residual_ratio > 0.8 {
        score += 180.0; // high waste
    } else if residual_ratio > 0.4 && residual_ratio < 0.6 {
        score -= 10.0; // good middle ground
    }

    // Soft penalty for many open bins
    score += (open_bins_count as f64).sqrt() * 0.25;

    // Progress‑dependent emphasis on tight packing
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    if progress > 0.95 {
        score += residual_ratio * 120.0 * (progress - 0.95);
    }

    // Item size fraction bonus/penalty
    let item_frac = item_size as f64 / bin_cap_f;
    if item_frac > 0.9 {
        score += 30.0;
    } else if item_frac > 0.7 {
        score += 12.0;
    }

    // Look‑ahead adjustment
    if next_item_size > 0 {
        let diff = next_item_size as i32 - post_residual as i32;
        if diff > 0 {
            // Next item too large for remaining space – prefer a new bin
            score -= diff as f64 * 0.3 + 40.0;
        } else if diff < -(post_residual as i32) / 5 {
            // Next item fits but leaves a very small gap – slightly reward
            score -= 8.0;
        }
    }

    // Fitting bins count handling
    if fitting_bins_count == 0 {
        score += 300.0;
    } else if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        score += (fitting_bins_count as f64).ln() * 1.0;
    }

    // Mean residual variance penalties
    let mean_diff = (mean_residual - post_residual_f).abs();
    if mean_diff > 15.0 {
        score += mean_diff * 0.05;
    }
    if mean_diff > 30.0 {
        score += (mean_diff - 30.0) * 0.03;
    }

    // Penalize bins far from the mean residual
    if (post_residual_f - mean_residual).abs() > 0.5 * mean_residual {
        score += (post_residual_f - mean_residual).abs() * 0.03;
    }

    // New‑bin candidate logic
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // Empty bin – encourage opening a new one
            score -= 20.0;
        } else {
            // There are fitting bins but the new bin is empty
            score += 30.0 + 2.0 * fitting_bins_count as f64;
        }
    }

    // Reward closeness to mean residual
    if (post_residual_f - mean_residual).abs() < 3.0 {
        score -= 5.0;
    }

    // Encourage opening a new bin when many are already open
    if open_bins_count > 8 {
        score += 0.02 * (open_bins_count as f64).powi(2);
    }

    score
}
